import express from "express";
import { fileURLToPath } from "node:url";
import {
  connectDB,
  getAllPlayers,
  findPlayersByTeam,
  findPlayersByMinRuns,
  getTopThreeRunScorers,
  addPlayer,
} from "./database.js";

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(fileURLToPath(new URL("./public", import.meta.url))));

function sendList(res, data, functionName) {
  if (!Array.isArray(data)) {
    return res.status(500).json({
      error: `${functionName}() did not return a list from the database. Complete it in database.js.`,
    });
  }
  res.json(data);
}

app.get("/api/players", async (req, res) => {
  try {
    sendList(res, await getAllPlayers(), "getAllPlayers");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/players/search", async (req, res) => {
  try {
    sendList(res, await findPlayersByTeam(req.query.team), "findPlayersByTeam");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/players/filter", async (req, res) => {
  const minRuns = Number(req.query.minRuns);
  if (Number.isNaN(minRuns)) {
    return res.status(400).json({ error: "Please enter a number." });
  }
  try {
    sendList(res, await findPlayersByMinRuns(minRuns), "findPlayersByMinRuns");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/players/top", async (req, res) => {
  try {
    sendList(res, await getTopThreeRunScorers(), "getTopThreeRunScorers");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post("/api/players", async (req, res) => {
  try {
    const saved = await addPlayer(req.body);
    if (!saved) {
      return res.status(500).json({
        error: "addPlayer() did not return the saved player. Complete it in database.js.",
      });
    }
    res.status(201).json(saved);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

try {
  await connectDB();
} catch (err) {
  console.log("Could not connect to MongoDB:", err.message);
}

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
